import{_ as e,c as a,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const A=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/faq.md","filePath":"ja/guide/faq.md","lastUpdated":1793163976000}'),r={name:"ja/guide/faq.md"};function s(n,p,o,u,c,l){return t(),a("div",null,[...p[0]||(p[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Q: NueZip とは何ですか？</p><p>A: NueZip は macOS 向けのプロフェッショナルなアーカイブマネージャーであり、RAR、ZIP、7-Zip、TAR、GZIP、BZIP2 を含む複数のアーカイブフォーマットの圧縮と展開をサポートしています。</p><p>Q: どの macOS バージョンがサポートされていますか？</p><p>A: NueZip は macOS 14 Sonoma 以降を必要とし、Apple Silicon（M シリーズ）チップに最適化されています。</p><p>Q: NueZip をどのようにダウンロードしてインストールすればよいですか？</p><p>A: <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store</a>（推奨）からダウンロードするか、<a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a> から最新のリリースを取得してください。</p><p>Q: NueZip は無料ですか？</p><p>A: NueZip はコア機能を備えた無料試用版を提供しています。買い切りの購入により、バッチ操作、アーカイブ修復、高度な暗号化を含む全機能のセットがアンロックされます。</p><p>Q: どのフォーマットがサポートされていますか？</p><p>A: <strong>読み取り</strong>: RAR、ZIP、7-Zip、TAR、GZIP、BZIP2、XZ、Zstandard<br><strong>書き込み（圧縮）</strong>: ZIP、7-Zip、TAR、GZIP、BZIP2、XZ、Zstandard<br> 完全なフォーマットマトリックスについては <a href="/ja/guide/introduction.html">はじめに</a> を参照してください。</p><p>Q: NueZip で RAR アーカイブを作成できますか？</p><p>A: いいえ。NueZip は RAR アーカイブを <strong>読み取る</strong> ことはできますが（マルチボリュームや修復済みのアーカイブを含む）、RAR の圧縮はライセンス制限によりサポートされていません。</p><p>Q: NueZip は機密ファイルに安全ですか？</p><p>A: はい。NueZip は完全にオフラインで動作します。すべての操作はお使いの Mac 上でローカルに実行されます。パスワードで保護された ZIP アーカイブには AES-256 暗号化を利用できます。</p><p>Q: NueZip は私のファイルをクラウドにアップロードしますか？</p><p>A: いいえ。NueZip は完全にオフラインのアプリケーションです。お客様のファイルがどこかにアップロードされることはありません。圧縮や展開にインターネット接続は不要です。</p><p>Q: アプリを更新するにはどうすればよいですか？</p><p>A: Mac App Store（自動）を通じて、または GitHub Releases から最新のリリースをダウンロードして更新してください。</p><p>Q: バグを報告したり機能をリクエストしたりするにはどうすればよいですか？</p><p>A: <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub リポジトリ</a> で issue を作成してください。macOS のバージョン、NueZip のバージョン、再現手順を含めてください。</p><p>Q: ログとデータはどこに保存されますか？</p><p>A: サンドボックス化された（App Store の）ビルドの場合：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Application Support/com.w3cub.nuezip/</span></span></code></pre></div><p>開発ビルドはログをコンソールに出力する場合があります。</p><p>さらに回答が必要な場合は、リポジトリで issue を作成するか、完全なドキュメントを参照してください。</p>',26)])])}const Z=e(r,[["render",s]]);export{A as __pageData,Z as default};
